from pathlib import Path
p=Path('/home/ubuntu/orbitpress5/app/src/main/assets/index.html')
s=p.read_text()
css='''
    .pipeline-grid{display:grid;gap:10px;margin-top:13px}.pipeline-card{padding:13px;border:1px solid #d7e0ee;border-radius:14px;background:#fbfdff}.pipeline-card h3{margin:0;color:var(--forest);font:700 16px Georgia,serif}.pipeline-card p{margin:5px 0 0;color:var(--muted);font-size:11px}.pipeline-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:12px}.pipeline-kpi{padding:10px 5px;border:1px solid var(--line);border-radius:11px;background:#f8fbff;text-align:center}.pipeline-kpi b{display:block;color:var(--forest);font:700 21px Georgia,serif}.pipeline-kpi span{display:block;margin-top:3px;color:var(--muted);font-size:9px}.pipeline-status{display:inline-block;margin-top:8px;padding:4px 8px;border-radius:99px;background:#e5f0ff;color:#315b9f;font-size:10px;font-weight:800}.pipeline-status.published{background:#d9fff1;color:#116b57}.pipeline-status.ready{background:#e4eaff;color:#3853a1}.pipeline-status.planned{background:#fff0d7;color:#946326}.cluster-list{display:flex;flex-wrap:wrap;gap:6px;margin-top:9px}.cluster-chip{padding:6px 8px;border-radius:9px;background:#eef5ff;color:#315b9f;font-size:11px}.brief-box{margin-top:10px;padding:10px;border-left:3px solid var(--cobalt);background:#f1f7ff;color:#38506e;font-size:11px;line-height:1.5}.calendar-row{display:grid;grid-template-columns:92px 1fr auto;gap:9px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line)}.calendar-row:last-child{border-bottom:0}.calendar-date{color:var(--cobalt);font-size:11px;font-weight:800}.pipeline-actions{display:flex;flex-wrap:wrap;gap:6px;margin-top:11px}.pipeline-actions .small-button{margin:0}@media(max-width:390px){.pipeline-kpis{grid-template-columns:repeat(2,1fr)}.calendar-row{grid-template-columns:1fr}.calendar-row .small-button{justify-self:start}}
'''
if '.pipeline-grid{' not in s:s=s.replace('</style>',css+'</style>',1)
menu='<button class="menu-item" data-screen="pipeline" type="button"><span class="menu-icon">◈</span>Editorial Pipeline</button>'
