section='''<section class="screen" id="screen-pipeline"><p class="eyebrow">OrbitPress 5.0</p><h1 class="screen-title">Editorial Pipeline</h1><p class="screen-subtitle">Plan, brief, review, and track content from idea to manual publication. This workspace never publishes automatically.</p><section class="card"><div class="section-head"><div><h2>Content planning</h2><p>Local planning data for the active website.</p></div><span class="tag">local only</span></div><div class="pipeline-kpis" id="pipelineKpis"></div><div class="pipeline-actions"><button id="createBrief" class="small-button" type="button">Create content brief</button><button id="addCalendarItem" class="small-button plain" type="button">Add calendar item</button></div></section><section class="card"><h2>Content brief</h2><p class="helper">Choose a queued keyword. The brief is saved locally and does not call an API or change the draft.</p><select id="briefKeyword"></select><label for="briefAudience">Audience</label><input id="briefAudience" placeholder="e.g. busy home cooks"><label for="briefIntent">Search intent</label><select id="briefIntent"><option>Informational</option><option>Commercial investigation</option><option>How-to</option><option>Recipe roundup</option></select><div id="briefPreview" class="brief-box">No brief selected.</div></section><section class="card"><h2>Keyword clusters</h2><p class="helper">Group related ideas locally to reduce duplicate topics.</p><input id="clusterName" placeholder="Cluster name"><textarea id="clusterKeywords" rows="3" placeholder="One supporting keyword per line"></textarea><button id="saveCluster" class="button secondary" type="button">Save keyword cluster</button><div id="clusterList" class="cluster-list"></div></section><section class="card"><h2>Content calendar</h2><p class="helper">Dates are planning reminders only. Publishing remains manual.</p><div id="calendarList"></div></section><section class="card"><h2>Pipeline records</h2><p class="helper">A local view of keywords, drafts, SEO review, images, and publication history.</p><div id="pipelineRecords" class="pipeline-grid"></div></section></section>'''
s=s.replace('<section class="screen" id="screen-settings">',section+'<section class="screen" id="screen-settings">',1)
functions='''function pipelineData(){if(!Array.isArray(state.workspace.contentBriefs))state.workspace.contentBriefs=[];if(!Array.isArray(state.workspace.keywordClusters))state.workspace.keywordClusters=[];if(!Array.isArray(state.workspace.calendarItems))state.workspace.calendarItems=[];return state.workspace}function renderPipeline(){const data=pipelineData(),keywords=activeKeywords(),drafts=activeDrafts(),published=drafts.filter(item=>item.generationStatus==='published'),ready=drafts.filter(item=>item.generationStatus==='ready');$('pipelineKpis').innerHTML=[['Ideas',keywords.length],['Drafts',drafts.length],['Ready',ready.length],['Published',published.length]].map(item=>`<div class="pipeline-kpi"><b>${item[1]}</b><span>${item[0]}</span></div>`).join('');const select=$('briefKeyword');select.innerHTML='<option value="">Choose a keyword</option>'+keywords.slice(0,100).map(item=>`<option value="${escapeHtml(item.id)}">${escapeHtml(item.keyword)}</option>`).join('');const latest=data.contentBriefs[0];if(latest&&select&&!select.value)select.value=latest.keywordId||'';renderBriefPreview();$('clusterList').innerHTML=data.keywordClusters.length?data.keywordClusters.slice(0,30).map(item=>`<span class="cluster-chip"><b>${escapeHtml(item.name)}</b>: ${escapeHtml(item.keywords.join(' · '))}</span>`).join(''):'<span class="helper">No keyword clusters saved yet.</span>';const dates=data.calendarItems.filter(item=>!item.siteId||item.siteId===activeSiteId()).sort((a,b)=>String(a.date).localeCompare(String(b.date)));$('calendarList').innerHTML=dates.length?dates.map(item=>`<div class="calendar-row"><span class="calendar-date">${escapeHtml(item.date)}</span><div><b>${escapeHtml(item.title)}</b><div class="queue-meta">${escapeHtml(item.note||'Planning reminder')}</div></div><button class="small-button remove" data-remove-calendar="${escapeHtml(item.id)}" type="button">Remove</button></div>`).join(''):'<div class="empty">No calendar items yet. Add a planning reminder.</div>';$('calendarList').querySelectorAll('[data-remove-calendar]').forEach(btn=>btn.onclick=()=>{data.calendarItems=data.calendarItems.filter(item=>item.id!==btn.dataset.removeCalendar);persist();renderPipeline()});const rows=keywords.slice(0,50).map(item=>{const draft=item.draftId?getDraft(item.draftId):null;const status=draft?.generationStatus||item.status||'planned';return `<article class="pipeline-card"><h3>${escapeHtml(item.keyword)}</h3><p>${escapeHtml(item.nicheProfile||'food')} · ${escapeHtml(item.contentType||'article')} · ${escapeHtml(item.priority||'normal')} priority</p><span class="pipeline-status ${escapeHtml(status)}">${escapeHtml(status)}</span>${draft?`<div class="queue-meta">${escapeHtml(draft.title)} · SEO audit available in Review</div>`:''}</article>`}).join('');$('pipelineRecords').innerHTML=rows||'<div class="empty"><strong>Pipeline is ready</strong>Add keywords in Content Studio to begin planning.</div>'}function renderBriefPreview(){const data=pipelineData(),id=$('briefKeyword')?.value,keyword=getKeyword(id),brief=data.contentBriefs.find(item=>item.keywordId===id&&(!item.siteId||item.siteId===activeSiteId()));$('briefPreview').innerHTML=brief?`<b>${escapeHtml(brief.title)}</b><br>Audience: ${escapeHtml(brief.audience)} · Intent: ${escapeHtml(brief.intent)}<br>Outline: ${escapeHtml(brief.outline)}<br><span class="helper">Created ${escapeHtml(formatDate(brief.createdAt))}. This is guidance only.</span>`:keyword?`<b>${escapeHtml(keyword.keyword)}</b><br>Suggested brief: define the audience, answer the core question, use practical H2 sections, and connect this topic to two related internal links.<br><span class="helper">Click Create content brief to save this locally.</span>`:'No brief selected.'}function createContentBrief(){const data=pipelineData(),id=$('briefKeyword').value,keyword=getKeyword(id);if(!keyword)return notice('Choose a queued keyword first.','bad');const title=`${keyword.keyword} — content brief`;const brief={id:makeId('brief'),siteId:activeSiteId(),keywordId:id,title,audience:$('briefAudience').value.trim()||'Readers searching for practical, trustworthy guidance',intent:$('briefIntent').value,outline:'Benefit-led introduction; practical H2 sections; FAQ or variations; conclusion and internal links',createdAt:Date.now()};data.contentBriefs=[brief,...data.contentBriefs.filter(item=>item.keywordId!==id||item.siteId!==activeSiteId())].slice(0,100);persist();renderBriefPreview();notice('Content brief saved locally. It does not modify or generate the article.','good')}function saveKeywordCluster(){const name=$('clusterName').value.trim(),words=$('clusterKeywords').value.split(/[\\n,;]+/).map(item=>item.trim()).filter(Boolean).slice(0,30);if(!name||!words.length)return notice('Enter a cluster name and at least one keyword.','bad');const data=pipelineData();data.keywordClusters.unshift({id:makeId('cluster'),siteId:activeSiteId(),name,keywords:words,createdAt:Date.now()});$('clusterName').value='';$('clusterKeywords').value='';persist();renderPipeline();notice('Keyword cluster saved locally.','good')}function addPipelineCalendarItem(){const title=window.prompt('Calendar item title');if(!title||!title.trim())return;const date=window.prompt('Planned date (YYYY-MM-DD)',new Date().toISOString().slice(0,10));if(!date||!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(date))return notice('Use a date in YYYY-MM-DD format.','bad');const data=pipelineData();data.calendarItems.push({id:makeId('calendar'),siteId:activeSiteId(),title:title.trim().slice(0,160),date,note:'Manual publishing reminder',createdAt:Date.now()});persist();renderPipeline();notice('Calendar reminder saved locally.','good')}'''
s=s.replace('function showScreen(name){',functions+'function showScreen(name){',1)
s=s.replace("if(name==='settings')renderSettings();", "if(name==='settings')renderSettings();if(name==='pipeline')renderPipeline();",1)
s=s.replace("document.querySelectorAll('.menu-item[data-screen]').forEach(button=>button.onclick=()=>showScreen(button.dataset.screen));showScreen('studio')", "document.querySelectorAll('.menu-item[data-screen]').forEach(button=>button.onclick=()=>showScreen(button.dataset.screen));$('createBrief').onclick=createContentBrief;$('briefKeyword').onchange=renderBriefPreview;$('saveCluster').onclick=saveKeywordCluster;$('addCalendarItem').onclick=addPipelineCalendarItem;showScreen('studio')",1)
